#!/bin/bash
set -e

# ============================================
# CodeForge - Self-Extracting Deployment Script
# ============================================
# Usage: Copy this entire script and paste it into
# GCP Cloud Shell or a GCP VM terminal.
# ============================================

echo "============================================="
echo "  CodeForge - Extracting Project"
echo "============================================="

# Create project directory
mkdir -p ~/codeforge && cd ~/codeforge

# Decode and extract
echo "Extracting project files..."
base64 --decode << 'BASE64_PAYLOAD' | tar xzf -

BASE64_PAYLOAD

echo "  Files extracted to ~/codeforge"
ls -la

# Bootstrap
echo ""
echo "============================================="
echo "  Setting up environment..."
echo "============================================="

# Create venv
python3 -m venv .venv
source .venv/bin/activate
echo "  Virtual environment created"

# Install deps
pip install --quiet --upgrade pip
pip install --quiet google-adk google-cloud-storage pypdf pydantic python-dotenv httpx requests
echo "  Dependencies installed"

# Setup .env
cp .env.example .env
echo "  Created .env from template"

echo ""
echo "============================================="
echo "  CodeForge extracted and ready!"
echo "============================================="
echo ""
echo "  Project location: ~/codeforge"
echo ""
echo "  Next steps:"
echo "  1. cd ~/codeforge"
echo "  2. source .venv/bin/activate"
echo "  3. nano .env                      # Set GOOGLE_CLOUD_PROJECT"
echo "  4. bash setup_environment.sh       # Enable APIs, create bucket"
echo "  5. python3 dry_run.py              # Validate"
echo "  6. adk web --port 8080             # Launch"
echo ""
